/* eslint-disable react/require-default-props */
/* eslint-disable react/no-unused-prop-types */
import React, { forwardRef } from 'react';
import { styled } from '@hexa-ui/theme';
import { ChevronRight } from '@hexa-ui/icons';
import { ListItemComponent, ListItemProps, PolymorphicRef } from './ListItem.types';
import { Divider } from '../divider';

const ListItem: ListItemComponent = forwardRef(
  <C extends React.ElementType = 'li'>(
    {
      as,
      children,
      divider = false,
      spacing = 'none',
      variant = 'base',
      disabled,
      ...restProps
    }: ListItemProps<C>,
    forwardedRef?: PolymorphicRef<C>
  ) => {
    const WrapperEl = as ?? 'li';

    return (
      <>
        <WrapperEl
          {...restProps}
          disabled={disabled}
          onClick={
            disabled
              ? undefined
              : ((restProps as Record<string, unknown>).onClick as
                  | React.MouseEventHandler<HTMLLIElement>
                  | undefined)
          }
          ref={forwardedRef}
        >
          <StyledContentContainer
            variant={variant}
            disabled={disabled || (restProps as Record<string, unknown>).disabled}
          >
            <StyledContent spacing={spacing} variantType={variant}>
              {children}
            </StyledContent>
            {variant === 'navigation' && (
              <StyledNavigationIconContainer spacing={spacing}>
                <ChevronRight size="medium" />
              </StyledNavigationIconContainer>
            )}
          </StyledContentContainer>
        </WrapperEl>
        {divider && <Divider orientation="horizontal" data-testid="divider" />}
      </>
    );
  }
);

const StyledContent = styled('div', {
  flexGrow: 1,
  minHeight: '56px',
  display: 'flex',
  alignItems: 'center',
  background: '$interfaceSurfaceClear',
  variants: {
    spacing: {
      none: {},
      medium: {
        padding: '0 $4',
      },
      large: {
        padding: '0 $6',
      },
    },
    // Declaring the variantType with empty values because of TS bug
    variantType: { navigation: {}, base: {}, selectable: {} },
  },
  compoundVariants: [
    {
      variantType: 'navigation',
      spacing: 'medium',
      css: {
        padding: '0',
        paddingLeft: '$4',
      },
    },
    {
      variantType: 'navigation',
      spacing: 'large',
      css: {
        padding: '0',
        paddingLeft: '$6',
      },
    },
  ],
});

const StyledNavigationIconContainer = styled('div', {
  display: 'flex',
  alignItems: 'center',
  paddingLeft: '$4',
  minHeight: '56px',
  variants: {
    spacing: {
      none: {},
      medium: {
        paddingRight: '$4',
      },
      large: {
        paddingRight: '$6',
      },
    },
  },
});

const StyledContentContainer = styled('div', {
  display: 'flex',
  alignItems: 'center',
  minHeight: '56px',
  padding: 0,
  color: '$interfaceLabelPrimary',
  fontFamily: '$paragraph',
  cursor: 'default',
  fontSize: '$3',
  lineHeight: '$6',
  variants: {
    variant: {
      base: {},
      navigation: {
        cursor: 'pointer',
        '&:hover': {
          background: '$brandAccentNeutralBackground',
        },
        '&:active': {
          background: '$brandAccentNeutralBasis',
        },
      },
      selectable: {
        cursor: 'pointer',
        '&:hover': {
          background: '$brandAccentNeutralBackground',
        },
        '&:active': {
          background: '$brandAccentNeutralBasis',
        },
      },
    },
    disabled: {
      true: {
        color: '$interfaceLabelDisabled',
        cursor: 'default',
        pointerEvents: 'none',
      },
      false: {},
    },
  },
  '&:hover': {},
});

export default ListItem;
